// sidebar group headings (their English names stay the identity in workspaces.config.ts).
// `en` is generated by scripts/i18n/extract.mjs (the workspace anchor in workspaces.config.ts
// plus every manifest menu `group`); collected into the admin layout's ui-messages by the registry.
import en from './en.json';
import tr from './tr.json';

export const dictionaries: Record<string, Record<string, string>> = { en, tr };
